import{_ as a,b as t,e as n,a7 as i}from"./chunks/framework.BCCJKnGb.js";const u=JSON.parse('{"title":"Agent 接入常见问题","description":"国新学伴 Agent 接入的常见问题：打不开、不引用、编造、隐私。","frontmatter":{"title":"Agent 接入常见问题","description":"国新学伴 Agent 接入的常见问题：打不开、不引用、编造、隐私。","type":"agent-faq","tags":["Agent","FAQ"],"updated":"2026-11-06T00:00:00.000Z"},"headers":[],"relativePath":"agent/faq.md","filePath":"agent/faq.md","lastUpdated":null}'),l={name:"agent/faq.md"};function o(r,e,d,s,h,c){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="agent-接入常见问题" tabindex="-1">Agent 接入常见问题 <a class="header-anchor" href="#agent-接入常见问题" aria-label="Permalink to &quot;Agent 接入常见问题&quot;">​</a></h1><h2 id="打不开-index-json" tabindex="-1">打不开 index.json <a class="header-anchor" href="#打不开-index-json" aria-label="Permalink to &quot;打不开 index.json&quot;">​</a></h2><ol><li>浏览器直接打开 <code>https://你的域名/agent/index.json</code>，看是否返回 JSON。</li><li>如果浏览器能开、Agent 不能开，可能是 Agent 没有联网权限，改用 <code>content.md</code>。</li><li>如果浏览器也打不开，换网络/换设备；仍不行就是部署问题。</li></ol><h2 id="agent-不引用来源" tabindex="-1">Agent 不引用来源 <a class="header-anchor" href="#agent-不引用来源" aria-label="Permalink to &quot;Agent 不引用来源&quot;">​</a></h2><ul><li>在提示词里明确：“每个结论必须附页面链接；没有链接就重答。”</li><li>给它具体页面：“请读 <code>/programs/2024</code>，只根据这一页回答。”</li><li>如果它仍不引用，换一个支持联网的 Agent。</li></ul><h2 id="agent-编造课程-学分" tabindex="-1">Agent 编造课程/学分 <a class="header-anchor" href="#agent-编造课程-学分" aria-label="Permalink to &quot;Agent 编造课程/学分&quot;">​</a></h2><ul><li>要求它“先列出读过的页面，再回答”。</li><li>关键政策让它引用原文；没有原文就说“没有找到”。</li><li>不要问“你觉得”“大概是”这类问题。</li></ul><h2 id="能不能查-申请版-保研资料" tabindex="-1">能不能查“申请版”保研资料？ <a class="header-anchor" href="#能不能查-申请版-保研资料" aria-label="Permalink to &quot;能不能查“申请版”保研资料？&quot;">​</a></h2><p>不能。公开版已脱敏；申请版只通过人工申请，不进入 Agent 索引。</p><h2 id="会不会泄露我的隐私" tabindex="-1">会不会泄露我的隐私？ <a class="header-anchor" href="#会不会泄露我的隐私" aria-label="Permalink to &quot;会不会泄露我的隐私？&quot;">​</a></h2><p>站点不收集个人信息；但你的 Agent 可能把对话发给模型厂商。不要输入成绩、学号、联系方式、offer 细节。</p><h2 id="为什么没有-mcp" tabindex="-1">为什么没有 MCP？ <a class="header-anchor" href="#为什么没有-mcp" aria-label="Permalink to &quot;为什么没有 MCP？&quot;">​</a></h2><p>本期是两天上线的只读版，优先保证“能打开、能查、能引用”。MCP 需要服务器、OAuth、权限和审计，等站点稳定后再做。</p>',13)])])}const p=a(l,[["render",o]]);export{u as __pageData,p as default};
